        while (second != null) {
            ListNode next = second.next;
            second.next = prev; prev = second; second = next;
        }
        ListNode first = head;
        while (prev != null) {
            ListNode a = first.next, b = prev.next;
            first.next = prev; prev.next = a;
            first = a; prev = b;
        }
    }
}

